package com.example.app;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    private App() {
    }

    public static void main(String[] args) {
        log.info("Application starting");
        Greeter greeter = new Greeter();
        log.debug("Created greeter: {}", greeter);
        String message = greeter.greet("World");
        log.info("Greeting produced: {}", message);
        log.info("Application finished");
    }
}

package com.example.app;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Greeter {

    private static final Logger log = LoggerFactory.getLogger(Greeter.class);

    public String greet(String name) {
        if (name == null || name.isBlank()) {
            log.warn("Received blank name; defaulting to 'World'");
            name = "World";
        }
        log.debug("Building greeting for {}", name);
        return "Hello, " + name + "!";
    }
}

package com.example.app;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class GreeterTest {

    private final Greeter greeter = new Greeter();

    @Test
    void greetsByName() {
        assertEquals("Hello, Ada!", greeter.greet("Ada"));
    }

    @Test
    void defaultsBlankNameToWorld() {
        assertEquals("Hello, World!", greeter.greet("  "));
        assertEquals("Hello, World!", greeter.greet(null));
    }
}

